using KitWright.Editor.Tools.Scripting;
using UnityEngine;
using UnityEditor;
using System.Text;

public class CommandScript : IKitWrightCommand
{
    public void Execute(ExecutionContext ctx)
    {
        var sb = new StringBuilder();
        foreach (var t in Resources.FindObjectsOfTypeAll<Transform>())
        {
            if (EditorUtility.IsPersistent(t.gameObject)) continue;
            if (t.name != "Yellow_HUD_Root") continue;
            var content = t.parent;
            sb.AppendLine("Yellow parent=" + (content != null ? content.name : "null"));
            if (content != null)
            {
                for (int i = 0; i < content.childCount; i++)
                {
                    var c = content.GetChild(i);
                    sb.AppendLine("  sibling/child: " + c.name + " active=" + c.gameObject.activeSelf);
                }
            }
            void Dump(Transform x, int d)
            {
                if (d > 2) return;
                sb.AppendLine(new string(' ', d * 2) + x.name + " active=" + x.gameObject.activeSelf);
                for (int i = 0; i < x.childCount; i++) Dump(x.GetChild(i), d + 1);
            }
            Dump(t, 0);
        }

        var preview = Object.FindObjectsOfType<Railbound.UI.LobbyCharacterPreviewManager>(true);
        sb.AppendLine("PreviewManagers=" + preview.Length);
        foreach (var p in preview)
        {
            sb.AppendLine("  " + p.gameObject.name + " active=" + p.gameObject.activeInHierarchy);
            var so = new SerializedObject(p);
            sb.AppendLine("  anchor=" + (so.FindProperty("characterSpawnAnchor").objectReferenceValue != null));
            sb.AppendLine("  ops=" + so.FindProperty("operators").arraySize);
        }

        var custom = Object.FindObjectsOfType<Railbound.UI.LobbyCustomizationUI>(true);
        sb.AppendLine("CustomizationUI=" + custom.Length);

        var stage = GameObject.Find("LobbyCharacterStage");
        sb.AppendLine("stage=" + (stage != null));
        if (stage != null)
        {
            foreach (var c in stage.GetComponents<MonoBehaviour>())
                sb.AppendLine("  stageComp=" + c.GetType().Name);
            foreach (var c in stage.GetComponentsInChildren<MonoBehaviour>(true))
            {
                var n = c.GetType().Name;
                if (n.Contains("Lobby") || n.Contains("Preview") || n.Contains("Custom"))
                    sb.AppendLine("  childComp=" + n + " on=" + c.gameObject.name);
            }
        }

        ctx.ReturnValue = sb.ToString();
    }
}
